/// Binance venue configured from Dart.
enum WireBinanceVenue {
  /// Binance Spot API.
  spot,

  /// Binance USD-M Futures API.
  usdMFutures,
}

/// Value used to select an Upbit API region from Dart.
///
/// Pocket and KRW transfer APIs are available only in `Korea`.
enum WireUpbitRegion {
  /// Upbit Korea API.
  korea,

  /// Upbit Singapore API.
  singapore,

  /// Upbit Indonesia API.
  indonesia,

  /// Upbit Thailand API.
  thailand,
}
